public class Test {
    public static void main(String[] a) {
        java.util.List<?>[] r = new java.util.List<?>[1];
        String out = capture(() -> r[0] = OrderProcessor.process(java.util.List.of("tea", "milk", "jam")));
        int start = out.indexOf("Processing 3 items");
        if (!(start >= 0)) throw new AssertionError("start message missing");
        if (!(out.indexOf("Done", start) > start)) throw new AssertionError("Done missing or printed before start");
        if (!(java.util.List.of("TEA", "MILK", "JAM").equals(r[0]))) throw new AssertionError("behavior changed");
        System.out.println("PASS");
    }

    static String capture(Runnable r) {
        java.io.PrintStream original = System.out;
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buf, true));
        try { r.run(); } finally { System.setOut(original); }
        return buf.toString();
    }
}
